import{_ as i,c as a,o as t,ag as n}from"./chunks/framework.ymCRTBvy.js";const E=JSON.parse('{"title":"15.1_创建初始化字典","description":"","frontmatter":{},"headers":[],"relativePath":"swift/basics/15.1_创建初始化字典.md","filePath":"swift/basics/15.1_创建初始化字典.md"}'),h={name:"swift/basics/15.1_创建初始化字典.md"};function e(l,s,p,k,r,d){return t(),a("div",null,s[0]||(s[0]=[n(`<h1 id="_15-1-创建初始化字典" tabindex="-1">15.1_创建初始化字典 <a class="header-anchor" href="#_15-1-创建初始化字典" aria-label="Permalink to &quot;15.1_创建初始化字典&quot;">​</a></h1><h2 id="字典基础-键值对的魅力-✨" tabindex="-1">字典基础：键值对的魅力 ✨ <a class="header-anchor" href="#字典基础-键值对的魅力-✨" aria-label="Permalink to &quot;字典基础：键值对的魅力 ✨&quot;">​</a></h2><p>字典是Swift中一种非常强大的集合类型，它允许你存储无序的键值对。每个值都与一个唯一的键相关联，就像现实世界中的字典一样，每个词（键）都有一个对应的解释（值）。这种结构让数据查找变得极其高效，平均查找时间复杂度仅为O(1)！</p><h2 id="创建空字典-从零开始-🚀" tabindex="-1">创建空字典：从零开始 🚀 <a class="header-anchor" href="#创建空字典-从零开始-🚀" aria-label="Permalink to &quot;创建空字典：从零开始 🚀&quot;">​</a></h2><p>你可以使用两种主要方式来创建一个空字典。第一种是使用初始化语法，明确指定键和值的类型。例如，如果你想创建一个存储字符串键和整数值的空字典，可以这样写：</p><div class="language-swift vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">swift</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">var</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> emptyDictionary: [</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">String</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Int</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">print</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;空字典：</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">\\(emptyDictionary)</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 输出：空字典：[:]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>另一种更简洁的方式是让Swift进行类型推断。如果你在声明时没有提供初始值，Swift会根据上下文推断出字典的类型。</p><h2 id="使用字典字面量初始化-快速填充数据-💡" tabindex="-1">使用字典字面量初始化：快速填充数据 💡 <a class="header-anchor" href="#使用字典字面量初始化-快速填充数据-💡" aria-label="Permalink to &quot;使用字典字面量初始化：快速填充数据 💡&quot;">​</a></h2><p>最常见也是最方便的初始化字典的方式是使用字典字面量。你可以在创建字典的同时直接提供键值对。每个键值对之间用冒号 <code>:</code> 分隔，不同的键值对之间用逗号 <code>,</code> 分隔。</p><div class="language-swift vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">swift</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">var</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> airports: [</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">String</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">String</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;YYZ&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Toronto Pearson&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;LHR&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;London Heathrow&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">print</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;机场字典：</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">\\(airports)</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 输出：机场字典：[&quot;YYZ&quot;: &quot;Toronto Pearson&quot;, &quot;LHR&quot;: &quot;London Heathrow&quot;]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>你甚至可以省略类型注解，让Swift自动推断类型。只要你提供了初始的键值对，Swift就能轻松识别出键和值的类型。</p><h2 id="字典类型推断-swift的智能之处-🧠" tabindex="-1">字典类型推断：Swift的智能之处 🧠 <a class="header-anchor" href="#字典类型推断-swift的智能之处-🧠" aria-label="Permalink to &quot;字典类型推断：Swift的智能之处 🧠&quot;">​</a></h2><p>Swift的类型推断功能非常智能，可以大大简化你的代码。当你使用字典字面量初始化字典时，如果所有键的类型都相同，并且所有值的类型也相同，Swift就会自动推断出字典的类型。</p><div class="language-swift vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">swift</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">let</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> namesOfIntegers </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Zero&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;One&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Two&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// namesOfIntegers 的类型被推断为 [Int: String]</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">print</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;数字名称字典：</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">\\(namesOfIntegers)</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>这种方式让代码更简洁，也更容易阅读。你不需要每次都明确写出 <code>[KeyType: ValueType]</code>。</p><h2 id="字典的键类型要求-哈希化是关键-🔑" tabindex="-1">字典的键类型要求：哈希化是关键 🔑 <a class="header-anchor" href="#字典的键类型要求-哈希化是关键-🔑" aria-label="Permalink to &quot;字典的键类型要求：哈希化是关键 🔑&quot;">​</a></h2><p>字典的键必须遵循 <code>Hashable</code> 协议。这意味着键必须能够提供一个哈希值，以便字典能够快速地存储和查找它们。Swift的标准库类型，如 <code>String</code>、<code>Int</code>、<code>Double</code> 和 <code>Bool</code>，默认都遵循 <code>Hashable</code> 协议。</p><ul><li><strong>为什么需要哈希化？</strong> 哈希化允许字典将键映射到内存中的特定位置，从而实现O(1)的平均查找时间。</li><li><strong>自定义类型作为键：</strong> 如果你想使用自定义类型作为字典的键，你需要让你的自定义类型遵循 <code>Hashable</code> 协议。这通常意味着你需要实现 <code>hash(into:)</code> 方法和 <code>==</code> 运算符。</li></ul><p>例如，你可以创建一个存储用户ID和用户名的字典，其中用户ID是 <code>Int</code> 类型，用户名是 <code>String</code> 类型。这在实际应用中非常常见，比如管理用户数据。</p><div class="language-swift vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">swift</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">var</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> userScores: [</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">String</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Int</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Alice&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 95</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Bob&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 88</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Charlie&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 76</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">print</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;用户分数字典：</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">\\(userScores)</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 输出：用户分数字典：[&quot;Alice&quot;: 95, &quot;Bob&quot;: 88, &quot;Charlie&quot;: 76]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>通过这些方法，你可以轻松地创建和初始化字典，为你的Swift应用程序奠定坚实的数据存储基础！字典的灵活性和高效性将极大地提升你的开发体验。🚀</p>`,21)]))}const g=i(h,[["render",e]]);export{E as __pageData,g as default};
